import unittest
from reporter import export_lines,preview_lines
class ReportTest(unittest.TestCase):
    def test_export(self):
        self.assertEqual(export_lines([{"name":" Ada ","score":"07"}]),"Ada: 7\n")
    def test_preview(self):
        rows=[{"name":" Ada ","score":"07"},{"name":" ","score":"not-used"}]
        self.assertEqual(preview_lines(rows),["Ada: 7"])
        self.assertEqual(export_lines(rows),"Ada: 7\n")
    def test_empty_and_bad(self):
        self.assertEqual(export_lines([]),"")
        self.assertEqual(preview_lines([]),[])
        for fn in (export_lines,preview_lines):
            with self.assertRaises(ValueError):fn([{"name":"Ada","score":"bad"}])

